    #[case("a.mjs", Some(Language::JavaScript))]
    #[case("a.cjs", Some(Language::JavaScript))]
    #[case("a.rs", Some(Language::Rust))]
    #[case("a.d.ts", None)]
    #[case("a.d.mts", None)]
    #[case("a.d.cts", None)]
    #[case("src/types/global.d.ts", None)]
    #[case("a.d.js", Some(Language::JavaScript))]
