    fn ts_item() -> impl Strategy<Value = String> {
        let export = prop::sample::select(&["", "export ", "export default ", "declare ", "export declare "][..]);
        let decorator = prop::sample::select(&["", "@dec\n", "@dec({ a: '}' })\n"][..]);
