    }

    fn rs_item() -> impl Strategy<Value = String> {
        rs_leaf().prop_recursive(3, 24, 4, |inner| {
            let attrs = prop::sample::select(&["", "#[cfg(test)]\n", "#[cfg(all(test, unix))]\n", "#[cfg(not(test))]\n", "#[cfg(any(test, unix))]\n", "pub "][..]);
            (attrs, name(), prop::collection::vec((inner, gap()), 0..4)).prop_map(|(attrs, n, items)| {
                let body: String = items.into_iter().map(|(item, gap)| format!("{item}{gap}")).collect();
                format!("{attrs}mod {n} {{\n{}\n}}", indent(&body, "    "))
            })
        })
    }

    fn rs_source() -> impl Strategy<Value = String> {
        let inner_attr = prop::sample::select(&["", "", "", "#![allow(dead_code)]\n", "#![cfg(test)]\n", "//! crate doc é\n"][..]);
        (inner_attr, prop::collection::vec((rs_item(), gap()), 0..6), any::<bool>()).prop_map(|(inner, items, crlf)| {
            let source: String = std::iter::once(inner.to_owned()).chain(items.into_iter().map(|(item, gap)| format!("{item}{gap}"))).collect();
            if crlf { source.replace('\n', "\r\n") } else { source }
