    }
    let ts = analyze(Utf8Path::new("a.ts"), TS_SAMPLE);
    let names: Vec<_> = ts.blocks.iter().map(|b| (b.name.as_deref().unwrap(), b.parent_index)).collect();
    assert_eq!(names, [("Café", None), ("load", Some(0)), ("save", Some(0)), ("api", None), ("fetch", Some(3))]);
    let rs = analyze(Utf8Path::new("a.rs"), RUST_SAMPLE);
    let names: Vec<_> = rs.blocks.iter().chain(&rs.test_blocks).map(|b| (b.name.as_deref().unwrap(), b.parent_index)).collect();
    assert_eq!(
        names,
        [("outer", None), ("Foo", Some(0)), ("first", Some(1)), ("second", Some(1)), ("tests", None), ("works", Some(4))]
    );
}

