}

#[test]
fn blocks_that_partly_overlap_are_reported() {
    let found = tampered("a.ts", TS_SAMPLE, |blocks| {
        let next = blocks[2].span.start;
        blocks[1].span.end = next + 10;
        blocks[1].code = TS_SAMPLE[blocks[1].span.clone()].to_owned();
    });
