fn an_empty_span_is_out_of_bounds() {
    let found = tampered("a.ts", TS_SAMPLE, |blocks| blocks[1].span = 40..40);
    assert!(kinds(&found).contains(&Invariant::SpanInBounds), "{}", render(&found));
}

